92	    /**
93	     * Normalise a raw telephone number to E.164 form.
94	     *
95	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
96	     * code are kept when present; otherwise country code '+61' is assumed and a
97	     * single leading '0' is dropped from the national digits. The result must have
98	     * between 8 and 15 digits after the '+'.
99	     *
100	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
101	     * national-number length is additionally validated against that country code:
102	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
103	     * length is wrong for its country is rejected.
104	     *
105	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
106	     */
107	    static String toE164(String raw) {
108	        if (raw == null) {
109	            return null;
110	        }
111	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
112	        String digits;
113	        boolean explicitCountryCode;
114	        if (cleaned.startsWith("+")) {
115	            digits = cleaned.substring(1);
116	            explicitCountryCode = true;
117	        } else {
118	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
119	            digits = "61" + national;
120	            explicitCountryCode = false;
121	        }
122	        if (!digits.matches("[0-9]{8,15}")) {
123	            return null;
124	        }
125	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
126	            return null;
127	        }
128	        return "+" + digits;
129	    }
130	
131	    /**
132	     * Validate the national-number length of an E.164 number (its digits without the
133	     * leading '+') against the requirement for its country code: country code '+61'
134	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
135	     * without a configured length requirement are accepted unchanged.
136	     */
137	    private static boolean hasValidNationalLength(String digits) {
138	        if (digits.startsWith("61")) {
139	            return digits.length() - "61".length() == 9;
140	        }
141	        if (digits.startsWith("1")) {
142	            return digits.length() - "1".length() == 10;
143	        }
144	        return true;
145	    }
146	
147	    /**
148	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
149	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
150	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
151	     * input normalises to the empty string.
152	     */
153	    private static String normaliseIdentity(String value) {
154	        if (value == null) {
155	            return "";
156	        }
157	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
158	    }
159	
160	    /**
161	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
162	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
163	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
164	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
165	     * that is both stored and used for every address comparison.
166	     */
167	    static String normaliseAddress(String value) {
168	        if (value == null) {
169	            return "";
170	        }
171	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
172	        if (collapsed.isEmpty()) {
173	            return "";
174	        }
175	        String[] tokens = collapsed.split(" ");
176	        StringBuilder result = new StringBuilder();
177	        for (int i = 0; i < tokens.length; i++) {
178	            if (i > 0) {
179	                result.append(' ');
180	            }
181	            result.append(expandAddressAbbreviation(tokens[i]));
182	        }
183	        return result.toString();
184	    }
185	
186	    /**
187	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
188	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
189	     * returned unchanged.
190	     */
191	    private static String expandAddressAbbreviation(String token) {
192	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
193	        return switch (core) {
194	            case "ST" -> "STREET";
195	            case "RD" -> "ROAD";
196	            case "AVE" -> "AVENUE";
197	            default -> token;
198	        };
199	    }
200	
201	    /**
202	     * Derive the stable, shared household identifier for owners sharing a household. It is a
203	     * deterministic UUID over the normalised last-name and address, so every owner in the same
204	     * household resolves to the same value regardless of the order in which they were created.
205	     */
206	    private static String householdId(String lastNameKey, String addressKey) {
207	        String seed = lastNameKey + "�" + addressKey;
208	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
209	    }
210	
211	    /**
212	     * Build an owner's derived duplicate-detection identity key as
213	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
214	     * component contributes the empty string, and the email is lower-cased so the comparison is
215	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
216	     */
217	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
218	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
219	        String emailKey = email == null ? "" : email.toLowerCase();
220	        String household = householdId == null ? "" : householdId;
221	        return telephone + "|" + emailKey + "|" + household;
222	    }
223	
224	    /**
225	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
226	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
227	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
228	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
229	     * only on the owner's own region and identity, not on how many owners already exist.
230	     */
231	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
232	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
233	    }
234	
235	    /**
236	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
237	     */
238	    private static String hash8(String input) {
239	        try {
240	            byte[] digest = MessageDigest.getInstance("SHA-256")
241	                .digest(input.getBytes(StandardCharsets.UTF_8));
242	            StringBuilder sb = new StringBuilder(digest.length * 2);
243	            for (byte b : digest) {
244	                sb.append(String.format("%02x", b));
245	            }
246	            return sb.substring(0, 8).toUpperCase();
247	        }
248	        catch (java.security.NoSuchAlgorithmException e) {
249	            throw new IllegalStateException(e);
250	        }
251	    }
252	
253	    /**
254	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
255	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
256	     * fixed city-to-region table, else {@code "UNKNOWN"}.
257	     */
258	    private static String region(String postcode, String city) {
259	        String fromPostcode = regionForPostcode(postcode);
260	        return fromPostcode != null ? fromPostcode : regionForCity(city);
261	    }
262	
263	    /**
264	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
265	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
266	     */
267	    private static String regionForPostcode(String postcode) {
268	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
269	            return null;
270	        }
271	        int value = Integer.parseInt(postcode);
272	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
273	            int[] range = entry.getValue();
274	            if (value >= range[0] && value <= range[1]) {
275	                return entry.getKey();
276	            }
277	        }
278	        return null;
279	    }
280	
281	    /**
282	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
283	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
284	     */
285	    static LocalDate toBusinessDay(LocalDate date) {
286	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
287	            date = date.plusDays(1);
288	        }
289	        return date;
290	    }
291	
292	    /**
293	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
294	     * using the same per-day accumulation path as the daily create-limit rule.
295	     */
296	    private long ownersCreatedOn(LocalDate registrationDate) {
297	        LocalDate day = toBusinessDay(registrationDate);
298	        return this.clinicService.findAllOwners().stream()
299	            .map(Owner::getRegistrationDate)
300	            .filter(existing -> existing != null)
301	            .map(OwnerRestControllerV1::toBusinessDay)
302	            .filter(day::equals)
303	            .count();
304	    }
305	
306	    /**
307	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
308	     * postcode against the owner's city region.
309	     */
310	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
311	        "NSW", new int[] {2000, 2099},
312	        "VIC", new int[] {3000, 3099},
313	        "QLD", new int[] {4000, 4099});
314	
315	    /**
316	     * Resolve an owner's region from the city using the fixed city-to-region table
317	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
318	     * when the city is not listed.
319	     */
320	    private static String regionForCity(String city) {
321	        return switch (city == null ? "" : city) {
322	            case "Sydney" -> "NSW";
323	            case "Melbourne" -> "VIC";
324	            case "Brisbane" -> "QLD";
325	            default -> "UNKNOWN";
326	        };
327	    }
328	
329	    /**
330	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
331	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
332	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
333	     */
334	    private static boolean isPostcodeValid(String postcode, String city) {
335	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
336	            return false;
337	        }
338	        int[] range = REGION_POSTCODES.get(regionForCity(city));
339	        if (range == null) {
340	            return true;
341	        }
342	        int value = Integer.parseInt(postcode);
343	        return value >= range[0] && value <= range[1];
344	    }
