361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
364	        Owner owner = this.clinicService.findOwnerById(ownerId);
365	        if (owner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
369	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
370	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
371	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
372	    }
