374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
377	        String telephone = toE164(ownerFieldsDto.getTelephone());
378	        if (telephone == null) {
379	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
380	        }
381	        String email = ownerFieldsDto.getEmail();
382	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
383	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
384	        }
385	        String address = normaliseAddress(ownerFieldsDto.getAddress());
386	        if (address.isEmpty()) {
387	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
388	        }
389	        String postcode = ownerFieldsDto.getPostcode();
390	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
391	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
392	        }
393	        if (ownerFieldsDto.getRegistrationDate() != null
394	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
395	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
396	        }
397	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
398	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
399	        LocalDate registrationDate = toBusinessDay(effectiveDate);
400	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
401	            .map(Owner::getRegistrationDate)
402	            .filter(existing -> existing != null)
403	            .map(OwnerRestControllerV1::toBusinessDay)
404	            .filter(registrationDate::equals)
405	            .count();
406	        if (ownersCreatedThatDay >= 100) {
407	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
408	        }
409	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
410	        long ownersInCity = this.clinicService.findAllOwners().stream()
411	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
412	            .count();
413	        if (ownersInCity >= 50) {
414	            return new ResponseEntity<>(HttpStatus.CONFLICT);
415	        }
416	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
417	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
418	        String addressKey = address;
419	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
420	            .filter(existing ->
421	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
422	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
423	            .toList();
424	        String householdId = (sharesHousehold && !householdMembers.isEmpty())
425	            ? householdId(lastNameKey, addressKey) : null;
426	        String identityKey = identityKey(telephone, email, householdId);
427	        boolean identityInUse = this.clinicService.findAllOwners().stream()
428	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
429	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
430	        if (identityInUse) {
431	            return new ResponseEntity<>(HttpStatus.CONFLICT);
432	        }
433	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
434	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
435	            .filter(existing ->
436	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
437	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
438	            .count();
439	        HttpHeaders headers = new HttpHeaders();
440	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
441	        owner.setNamesakeCount(namesakeCount);
442	        owner.setAddress(address);
443	        owner.setTelephone(telephone);
444	        owner.setEmail(email == null ? null : email.toLowerCase());
445	        owner.setRegistrationDate(registrationDate);
446	        owner.setCustomerCode(nextCustomerCode(
447	            region(postcode, owner.getCity()), telephone, owner.getLastName()));
448	        if (householdId != null) {
449	            owner.setHouseholdId(householdId);
450	            for (Owner member : householdMembers) {
451	                if (member.getHouseholdId() == null) {
452	                    member.setHouseholdId(householdId);
453	                    this.clinicService.saveOwner(member);
454	                }
455	            }
456	        }
457	        Integer possibleDuplicateOf = (postcode == null) ? null
458	            : this.clinicService.findAllOwners().stream()
459	                .filter(existing ->
460	                    normaliseIdentity(existing.getLastName()).equals(lastNameKey)
461	                        && postcode.equals(existing.getPostcode())
462	                        && !telephone.equals(toE164(existing.getTelephone())))
463	                .map(Owner::getId)
464	                .findFirst()
465	                .orElse(null);
466	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
467	        this.clinicService.saveOwner(owner);
468	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
469	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
470	            ownerMapper.formatMembershipLevel(owner));
471	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
472	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
473	        headers.setLocation(UriComponentsBuilder.newInstance()
474	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
475	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
476	    }
