478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
481	        String telephone = toE164(ownerFieldsDto.getTelephone());
482	        if (telephone == null) {
483	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
484	        }
485	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
486	        if (currentOwner == null) {
487	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
488	        }
489	        String email = ownerFieldsDto.getEmail();
490	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
491	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
492	        }
493	        currentOwner.setAddress(ownerFieldsDto.getAddress());
494	        currentOwner.setCity(ownerFieldsDto.getCity());
495	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
496	        currentOwner.setLastName(ownerFieldsDto.getLastName());
497	        currentOwner.setTelephone(telephone);
498	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
499	        this.clinicService.saveOwner(currentOwner);
500	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
501	    }
