525	        pet.setOwner(owner);
526	        pet.getType().setName(null);
527	        this.clinicService.savePet(pet);
528	        PetDto petDto = petMapper.toPetDto(pet);
529	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
530	            .buildAndExpand(pet.getId()).toUri());
531	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
532	    }
