534	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
535	    @Override
536	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
537	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
538	        if (currentOwner != null) {
539	            Pet currentPet = this.clinicService.findPetById(petId);
540	            if (currentPet != null) {
541	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
542	                currentPet.setName(petFieldsDto.getName());
543	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
